const seen = new Set(); const log = [];
const end = Date.parse("2026-10-22T17:41:00Z");
while (Date.now() < end - 15000) {
  const st = sdk.getState();
  if (!st || !st.player) break;
  if (st.player.isDead) { await bot.waitForCondition(s => !s.player?.isDead, 20000).catch(()=>{}); continue; }
  if (st.player.hp < 5 && st.inventory.some(i => /bread|shrimp/i.test(i.name))) await bot.eatFood().catch(()=>{});
  const cands = sdk.getNearbyNpcs().filter(n => !n.unreachable && !/guide|cook|banker|shop|sheep|cow|chicken|hans|fred|man$|woman/i.test(n.name) || /^(rat|man|goblin|chicken|cow)$/i.test(n.name)).sort((a,b)=>a.combatLevel-b.combatLevel);
  const t = cands.find(n => !seen.has(n.name)) || cands[0];
  if (!t) { await bot.walkTo(3222 + Math.floor(Math.random()*10)-5, 3218, 3).catch(()=>{}); continue; }
  const r = await bot.attack(t, 15000);
  log.push(`${t.name}(${t.combatLevel}): ${r.success ? 'ok' : r.reason}`);
  if (r.success) seen.add(t.name);
  await bot.waitForIdle(3000).catch(()=>{});
}
return { log: log.slice(-30), seen: [...seen] };

